package com.pgconnect.billing;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("payment_attempts") @CompoundIndex(name="resident_attempts",def="{'residentId':1,'createdAt':-1}")
public class PaymentAttempt {
 @Id private String id;private String residentId;private String ownerId;private String chargeId;private String propertyId;@Indexed(unique=true,sparse=true)private String providerOrderId;private String providerPaymentId;@Indexed(unique=true)private String idempotencyKey;private long amountPaise;private String currency="INR";private PaymentAttemptStatus status=PaymentAttemptStatus.PENDING;private Instant createdAt=Instant.now();private Instant confirmedAt;
 public String getId(){return id;}public String getResidentId(){return residentId;}public String getOwnerId(){return ownerId;}public String getChargeId(){return chargeId;}public String getPropertyId(){return propertyId;}public String getProviderOrderId(){return providerOrderId;}public String getProviderPaymentId(){return providerPaymentId;}public String getIdempotencyKey(){return idempotencyKey;}public long getAmountPaise(){return amountPaise;}public String getCurrency(){return currency;}public PaymentAttemptStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getConfirmedAt(){return confirmedAt;}
 public void setResidentId(String v){residentId=v;}public void setOwnerId(String v){ownerId=v;}public void setChargeId(String v){chargeId=v;}public void setPropertyId(String v){propertyId=v;}public void setProviderOrderId(String v){providerOrderId=v;}public void setProviderPaymentId(String v){providerPaymentId=v;}public void setIdempotencyKey(String v){idempotencyKey=v;}public void setAmountPaise(long v){amountPaise=v;}public void setCurrency(String v){currency=v;}public void setStatus(PaymentAttemptStatus v){status=v;}public void setConfirmedAt(Instant v){confirmedAt=v;}
}
